    private void loadApps(){
        all.clear();allInstalled.clear();tvInstalled.clear();mobileInstalled.clear();shown.clear();
        PackageManager pm=getPackageManager();Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);
        List<ResolveInfo> found=pm.queryIntentActivities(q,0);if(found.isEmpty()){q.removeCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);q.addCategory(Intent.CATEGORY_LAUNCHER);found=pm.queryIntentActivities(q,0);}
        HashSet<String> seen=new HashSet<>();for(ResolveInfo ri:found){String p=ri.activityInfo.packageName;if(p.equals(getPackageName())||!seen.add(p))continue;String label=ri.loadLabel(pm).toString();android.graphics.drawable.Drawable banner=ri.activityInfo.loadBanner(pm);android.graphics.drawable.Drawable icon=banner!=null?banner:ri.loadIcon(pm);
            // Give the stock Home tile the Army Dock identity inside this launcher only.
            if(label.equalsIgnoreCase("Màn hình chính")){label="Army Dock";icon=getDrawable(R.drawable.tv_banner);}
            AppItem item=new AppItem(label,p,icon);all.add(item);tvInstalled.add(item);}
        // The drawer includes both Android TV apps and regular APKs with launch activities.
        HashSet<String> installedPackages=new HashSet<>(seen);Intent regularQuery=new Intent(Intent.ACTION_MAIN);regularQuery.addCategory(Intent.CATEGORY_LAUNCHER);
        for(ResolveInfo ri:pm.queryIntentActivities(regularQuery,0)){String p=ri.activityInfo.packageName;if(p.equals(getPackageName())||!installedPackages.add(p))continue;mobileInstalled.add(new AppItem(ri.loadLabel(pm).toString(),p,ri.loadIcon(pm)));}
        allInstalled.addAll(tvInstalled);allInstalled.addAll(mobileInstalled);Collections.sort(all,(a,b)->a.label.compareToIgnoreCase(b.label));Collections.sort(tvInstalled,(a,b)->a.label.compareToIgnoreCase(b.label));Collections.sort(mobileInstalled,(a,b)->a.label.compareToIgnoreCase(b.label));Collections.sort(allInstalled,(a,b)->a.label.compareToIgnoreCase(b.label));android.content.SharedPreferences prefs=getSharedPreferences(PREF,0);String saved=prefs.getString("dock","");
        if(!prefs.getBoolean("dock_customized",false))shown.addAll(all);else if(!saved.isEmpty())for(String p:saved.split("\\|"))for(AppItem a:all)if(a.pkg.equals(p))shown.add(a);
    }
