    private void restoreDefaults(Dialog dialog){
        android.content.SharedPreferences prefs=getSharedPreferences(PREF,0);String oldWallpaper=prefs.getString("wallpaper_uri",null);
        if(oldWallpaper!=null)try{getContentResolver().releasePersistableUriPermission(Uri.parse(oldWallpaper),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}
        prefs.edit().remove("dock").putBoolean("dock_customized",false).remove("wallpaper_uri").remove("wallpaper_downloaded").remove("wallpaper_download_url").putBoolean("show_holidays",true).putInt("transparency_dock",75).putInt("transparency_time",30).putInt("transparency_apps",5).putInt("dock_focus_scale",8).putInt("dock_focus_lift",4).remove("transparency_buttons").remove("transparency_controls").apply();
        shown.clear();shown.addAll(all);deleteDownloadedWallpaper();applyWallpaper();applyTransparency();renderDock();dialog.dismiss();toast("Đã khôi phục cài đặt mặc định");
    }
