        TextView name=text(label,15,LIGHT,false);name.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);row.addView(name,new LinearLayout.LayoutParams(0,dp(56),1));Switch toggle=new Switch(this);toggle.setThumbTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{0xFFD4E8B5,0xFFBBC4B0}));toggle.setTrackTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{0xFF788760,0xFF4D5548}));toggle.setChecked(getSharedPreferences(PREF,0).getBoolean(key,defaultValue));toggle.setFocusable(false);row.addView(toggle,new LinearLayout.LayoutParams(-2,dp(48)));
