    private TextView locationDropdown(String label,String selected){TextView row=text(label+"    ▾  "+selected,15,LIGHT,false);row.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);row.setPadding(dp(14),0,dp(12),0);row.setSingleLine(true);row.setEllipsize(android.text.TextUtils.TruncateAt.END);row.setFocusable(true);row.setBackground(round(0x5534402C,dp(12)));row.setOnFocusChangeListener((v,focused)->{if(focused){GradientDrawable bg=round(0x6634402C,dp(12));bg.setStroke(dp(1),0xFFD4E8B5);row.setBackground(bg);}else row.setBackground(round(0x5534402C,dp(12)));});return row;}
    private void showLocationOptions(String titleText,ArrayList<String> options,String selected,java.util.function.Consumer<String> onSelected){Dialog choices=new Dialog(this);LinearLayout panel=menuPanel();TextView title=text(titleText,18,LIGHT,true);title.setGravity(Gravity.CENTER);panel.addView(title,new LinearLayout.LayoutParams(-1,dp(44)));ScrollView scroll=new ScrollView(this);LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);scroll.addView(rows);for(String option:options)addMenuRow(rows,(option.equals(selected)?"✓  ":"")+option,()->{choices.dismiss();onSelected.accept(option);});int listHeight=Math.min(dp(420),(int)(getResources().getDisplayMetrics().heightPixels*.68f));panel.addView(scroll,new LinearLayout.LayoutParams(-1,Math.min(dp(options.size()*48),listHeight)));choices.setContentView(panel);configureDialog(choices,dp(470));choices.show();configureDialog(choices,dp(470));if(rows.getChildCount()>0)rows.getChildAt(0).requestFocus();}
    private void searchWeatherLocations(String query,TextView status,LinearLayout results,LinearLayout resultsBox,Dialog dialog){
        resultsBox.setVisibility(View.GONE);results.removeAllViews();String term=query==null?"":query.trim();if(term.length()<2){toast("Nhập ít nhất 2 ký tự để tìm khu vực");return;}
        weatherExecutor.execute(()->{
            ArrayList<WeatherLocation> locations=new ArrayList<>();String error=null;
            try{
                String normalizedQuery=normalizeLocationText(term);String[] words=normalizedQuery.split("\\s+");
                JSONObject data=locationData();JSONArray provinces=data.getJSONArray("tinh"),units=data.getJSONArray("xa");
                for(int i=0;i<provinces.length();i++){
                    JSONArray row=provinces.getJSONArray(i);String name=row.getString(0);String label=name+" · Việt Nam";
                    if(matchesLocationQuery(normalizedQuery,words,label))locations.add(new WeatherLocation(name,label,i,row.getDouble(1),row.getDouble(2)));
                }
                for(int i=0;i<units.length();i++){
                    JSONArray row=units.getJSONArray(i);String name=row.getString(0);int provinceIndex=row.getInt(1);
                    if(provinceIndex<0||provinceIndex>=provinces.length())continue;
                    String province=provinces.getJSONArray(provinceIndex).getString(0);String label=name+" · "+province;
                    if(matchesLocationQuery(normalizedQuery,words,label))locations.add(new WeatherLocation(name,label,provinceIndex,row.getDouble(2),row.getDouble(3)));
                }
                Collections.sort(locations,(a,b)->{int sa=locationMatchScore(normalizedQuery,a.name),sb=locationMatchScore(normalizedQuery,b.name);return Integer.compare(sb,sa);});
            }catch(Exception e){error="Không đọc được danh sách địa điểm.";}
            final String message=error;
            runOnUiThread(()->{
                if(isFinishing()||isDestroyed())return;
                if(message!=null){toast("Không tìm được danh sách địa điểm");return;}
                if(locations.isEmpty()){toast("Không tìm thấy Phường/Xã phù hợp");return;}
                status.setText("Kết quả tìm kiếm");int shownCount=0;
                for(WeatherLocation location:locations){
                    if(shownCount++>=60)break;
                    addMenuRow(results,location.label,()->{
                        getSharedPreferences(PREF,0).edit().putString("weather_location",location.name).putInt("weather_province_index",location.provinceIndex).putFloat("weather_latitude",(float)location.latitude).putFloat("weather_longitude",(float)location.longitude).apply();
                        weatherInfo.setText(location.name+" · Đang cập nhật thời tiết…");dialog.dismiss();refreshWeatherIfNeeded(true);
                    });
                }
                resultsBox.setVisibility(View.VISIBLE);
            });
        });
    }
    private synchronized JSONObject locationData()throws Exception{if(cachedLocationData==null)cachedLocationData=new JSONObject(readLocationAsset());return cachedLocationData;}
    private String readLocationAsset()throws Exception{try(InputStreamReader reader=new InputStreamReader(getAssets().open("vietnam_locations.json"),StandardCharsets.UTF_8);BufferedReader buffered=new BufferedReader(reader)){StringBuilder json=new StringBuilder();String line;while((line=buffered.readLine())!=null)json.append(line);return json.toString();}}
    private String normalizeLocationText(String value){return java.text.Normalizer.normalize(value,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").replace('đ','d').replace('Đ','D').toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9 ]"," ").replaceAll("\\b(tinh|thanh pho|phuong|xa|dac khu)\\b"," ").replaceAll("\\s+"," ").trim();}
    private boolean matchesLocationQuery(String normalizedQuery,String[] words,String label){String normalizedLabel=normalizeLocationText(label);for(String word:words)if(!word.isEmpty()&&!normalizedLabel.contains(word))return false;return !normalizedQuery.isEmpty();}
    private int locationMatchScore(String query,String name){String normalizedName=normalizeLocationText(name);if(normalizedName.equals(query))return 3;if(normalizedName.startsWith(query))return 2;if(normalizedName.contains(query))return 1;return 0;}
    private String fetchText(String address)throws Exception{HttpURLConnection connection=(HttpURLConnection)new URL(address).openConnection();connection.setConnectTimeout(10000);connection.setReadTimeout(10000);connection.setRequestMethod("GET");connection.setRequestProperty("Accept","application/json");connection.setRequestProperty("User-Agent","ArmyLauncherLite/1.0");try{if(connection.getResponseCode()!=200)throw new java.io.IOException("HTTP "+connection.getResponseCode());StringBuilder body=new StringBuilder();try(BufferedReader reader=new BufferedReader(new InputStreamReader(connection.getInputStream(),StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null)body.append(line);}return body.toString();}finally{connection.disconnect();}}
    private void refreshWeatherIfNeeded(boolean force){if(!isInfoEnabled("show_weather",true))return;String location=getSharedPreferences(PREF,0).getString("weather_location",null);if(location==null||location.isEmpty()){if(weatherInfo!=null)weatherInfo.setText("Chọn khu vực trong Cài đặt");return;}long now=System.currentTimeMillis();android.content.SharedPreferences prefs=getSharedPreferences(PREF,0);lastWeatherFetch=Math.max(lastWeatherFetch,prefs.getLong("weather_last_fetch",0));if(!force&&now-lastWeatherFetch<WEATHER_REFRESH_INTERVAL_MS)return;lastWeatherFetch=now;prefs.edit().putLong("weather_last_fetch",now).apply();float lat=prefs.getFloat("weather_latitude",0),lon=prefs.getFloat("weather_longitude",0);weatherExecutor.execute(()->{String display;try{String url="https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,weather_code&timezone=auto";JSONObject current=new JSONObject(fetchText(url)).getJSONObject("current");int code=current.getInt("weather_code");double temp=current.getDouble("temperature_2m");display=location+" · "+weatherIcon(code)+" "+Math.round(temp)+"°C · "+weatherDescription(code);}catch(Exception e){display=location+" · Không tải được thời tiết";}final String result=display;runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&weatherInfo!=null&&isInfoEnabled("show_weather",true))weatherInfo.setText(result);});});}
    private String weatherIcon(int code){if(code==0)return "☀";if(code==1||code==2)return "⛅";if(code==3||code==45||code==48)return "☁";if(code>=95)return "⚡";if(code>=71&&code<=86)return "❄";if(code>=51&&code<=67||code>=80&&code<=82)return "☂";return "☁";}
    private String weatherDescription(int code){if(code==0)return "Trời quang";if(code==1)return "Ít mây";if(code==2)return "Có mây";if(code==3)return "Nhiều mây";if(code==45||code==48)return "Sương mù";if(code>=51&&code<=57)return "Mưa phùn";if(code>=61&&code<=67)return "Mưa";if(code>=71&&code<=77)return "Tuyết";if(code>=80&&code<=82)return "Mưa rào";if(code==85||code==86)return "Mưa tuyết";if(code==95||code==96||code==99)return "Dông";return "Thời tiết thay đổi";}
    private SeekBar addTransparencyControl(LinearLayout panel,String label,String key,int defaultValue){
        int initial=getSharedPreferences(PREF,0).getInt(key,defaultValue);LinearLayout section=new LinearLayout(this);section.setOrientation(LinearLayout.VERTICAL);section.setPadding(dp(8),dp(3),dp(8),dp(3));
        LinearLayout labelRow=new LinearLayout(this);labelRow.setGravity(Gravity.CENTER_VERTICAL);TextView name=text(label,14,LIGHT,false);labelRow.addView(name,new LinearLayout.LayoutParams(0,dp(28),1));TextView value=text(initial+"%",14,MUTED,true);value.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);labelRow.addView(value);section.addView(labelRow);
        SeekBar slider=new SeekBar(this);slider.setMax(100);slider.setProgress(initial);slider.setFocusable(true);slider.setFocusableInTouchMode(false);slider.setProgressTintList(android.content.res.ColorStateList.valueOf(OLIVE));slider.setThumbTintList(android.content.res.ColorStateList.valueOf(0xFFD4E8B5));section.addView(slider,new LinearLayout.LayoutParams(-1,dp(34)));
        slider.setOnFocusChangeListener((view,focused)->setSliderFocusAppearance(section,name,value,focused));
        slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar seekBar,int progress,boolean fromUser){value.setText(progress+"%");if(fromUser){getSharedPreferences(PREF,0).edit().putInt(key,progress).apply();applyTransparency();}}public void onStartTrackingTouch(SeekBar seekBar){}public void onStopTrackingTouch(SeekBar seekBar){}});
        panel.addView(section,new LinearLayout.LayoutParams(-1,dp(72)));return slider;
    }
