    private void showWallpaperUrlDialog(){Dialog dialog=new Dialog(this);LinearLayout panel=menuPanel();TextView title=text("Nhập URL hình nền",18,LIGHT,true);title.setGravity(Gravity.CENTER);panel.addView(title,new LinearLayout.LayoutParams(-1,dp(44)));TextView hint=text("Dán liên kết HTTPS trực tiếp đến ảnh (tối đa 20 MB).",13,MUTED,false);hint.setGravity(Gravity.CENTER);panel.addView(hint,new LinearLayout.LayoutParams(-1,dp(34)));EditText urlInput=new EditText(this);urlInput.setSingleLine(true);urlInput.setTextSize(15);urlInput.setTextColor(LIGHT);urlInput.setHintTextColor(MUTED);urlInput.setHint("example.com/wallpaper.jpg");urlInput.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);urlInput.setPadding(dp(12),0,dp(12),0);urlInput.setBackground(round(0x5534402C,dp(12)));urlInput.setText("https://");urlInput.setSelection(urlInput.length());panel.addView(urlInput,new LinearLayout.LayoutParams(-1,dp(48)));addMenuRow(panel,"Tải và áp dụng",()->{String url=urlInput.getText().toString().trim();if(url.isEmpty()||"https://".equalsIgnoreCase(url)){toast("Nhập địa chỉ HTTPS sau https://");return;}dialog.dismiss();downloadWallpaper(url);});addMenuRow(panel,"Hủy",dialog::dismiss);dialog.setContentView(panel);configureDialog(dialog,dp(470));dialog.show();configureDialog(dialog,dp(470));if(dialog.getWindow()!=null)dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);urlInput.requestFocus();}
    private void downloadWallpaper(String address){final String url=address.trim();if(!url.matches("(?i)^https://.+")){toast("URL hình nền cần bắt đầu bằng https://");return;}toast("Đang tải hình nền…");wallpaperExecutor.execute(()->{File temp=null;try{HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(20000);connection.setInstanceFollowRedirects(true);connection.setRequestMethod("GET");connection.setRequestProperty("Accept","image/*");connection.setRequestProperty("User-Agent","ArmyLauncherLite/1.0");try{int code=connection.getResponseCode();if(code!=200)throw new java.io.IOException("HTTP "+code);if(!"https".equalsIgnoreCase(connection.getURL().getProtocol()))throw new java.io.IOException("Chỉ hỗ trợ HTTPS");long declared=connection.getContentLengthLong();if(declared>20L*1024*1024)throw new java.io.IOException("Ảnh vượt quá 20 MB");File directory=new File(getFilesDir(),"wallpaper");if(!directory.exists()&&!directory.mkdirs())throw new java.io.IOException("Không tạo được thư mục hình nền");temp=new File(directory,"launcher-wallpaper.tmp");File saved=new File(directory,"launcher-wallpaper.img");long total=0;byte[] buffer=new byte[16384];try(BufferedInputStream input=new BufferedInputStream(connection.getInputStream());FileOutputStream output=new FileOutputStream(temp)){int read;while((read=input.read(buffer))!=-1){total+=read;if(total>20L*1024*1024)throw new java.io.IOException("Ảnh vượt quá 20 MB");output.write(buffer,0,read);}}BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getAbsolutePath(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new java.io.IOException("URL không trỏ trực tiếp đến tệp ảnh");if(saved.exists()&&!saved.delete())throw new java.io.IOException("Không thay được ảnh cũ");if(!temp.renameTo(saved))throw new java.io.IOException("Không lưu được hình nền");getSharedPreferences(PREF,0).edit().remove("wallpaper_uri").putBoolean("wallpaper_downloaded",true).putString("wallpaper_download_url",url).apply();Bitmap bitmap=decodeWallpaper(saved);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&wallpaper!=null&&bitmap!=null){wallpaperLoadToken++;wallpaper.setImageBitmap(bitmap);}toast("Đã tải và áp dụng hình nền");});}finally{connection.disconnect();}}catch(Exception e){if(temp!=null)temp.delete();String error=e.getMessage()==null?"Không tải được ảnh":e.getMessage();runOnUiThread(()->toast("Lỗi hình nền: "+error));}});}
    private Bitmap decodeWallpaper(File file){try{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),bounds);int targetW=Math.max(1,getResources().getDisplayMetrics().widthPixels),targetH=Math.max(1,getResources().getDisplayMetrics().heightPixels);int sample=1;while(bounds.outWidth/sample>targetW*2||bounds.outHeight/sample>targetH*2)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;return BitmapFactory.decodeFile(file.getAbsolutePath(),options);}catch(Exception ignored){return null;}}
    private void deleteDownloadedWallpaper(){File file=new File(new File(getFilesDir(),"wallpaper"),"launcher-wallpaper.img");if(file.exists())file.delete();File temp=new File(file.getParentFile(),"launcher-wallpaper.tmp");if(temp.exists())temp.delete();}
    private void applyWallpaper(){if(wallpaper==null)return;wallpaper.setImageResource(R.drawable.default_wallpaper);String saved=getSharedPreferences(PREF,0).getString("wallpaper_uri",null);if(saved!=null){try{wallpaper.setImageURI(Uri.parse(saved));if(wallpaper.getDrawable()!=null)return;}catch(Exception ignored){}}final int request=++wallpaperLoadToken;File downloaded=new File(new File(getFilesDir(),"wallpaper"),"launcher-wallpaper.img");boolean useDownloaded=getSharedPreferences(PREF,0).getBoolean("wallpaper_downloaded",false)&&downloaded.exists();wallpaperExecutor.execute(()->{Bitmap bitmap=useDownloaded?decodeWallpaper(downloaded):decodeDefaultWallpaper();runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&wallpaper!=null&&bitmap!=null&&request==wallpaperLoadToken)wallpaper.setImageBitmap(bitmap);});});}
    private Bitmap decodeDefaultWallpaper(){try{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeResource(getResources(),R.drawable.vietnampt,bounds);int targetW=Math.max(1,getResources().getDisplayMetrics().widthPixels),targetH=Math.max(1,getResources().getDisplayMetrics().heightPixels),sample=1;while(bounds.outWidth/sample>targetW||bounds.outHeight/sample>targetH)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;return BitmapFactory.decodeResource(getResources(),R.drawable.vietnampt,options);}catch(Exception ignored){return null;}}
    private void systemSettings(){try{startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}catch(Exception e){toast("Không mở được cài đặt TV");}}
    private void openWifi(){try{startActivity(new Intent(android.provider.Settings.ACTION_WIFI_SETTINGS));}catch(Exception e){systemSettings();}}
    private void openInputs(){
        refreshInputStatus();
        ArrayList<TvInputInfo> inputs=new ArrayList<>();try{TvInputManager manager=(TvInputManager)getSystemService(TV_INPUT_SERVICE);if(manager!=null)for(TvInputInfo info:manager.getTvInputList())if(info.isPassthroughInput())inputs.add(info);}catch(Exception ignored){}
        if(inputs.isEmpty()){toastCentered("TV này không công khai các cổng HDMI qua Android. Dùng nút INPUT/SOURCE trên remote để chọn cổng.");return;}
        Dialog dialog=new Dialog(this);LinearLayout panel=menuPanel();TextView title=text("Chọn nguồn vào",18,LIGHT,true);title.setGravity(Gravity.CENTER);panel.addView(title,new LinearLayout.LayoutParams(-1,dp(44)));
        for(TvInputInfo info:inputs){String label=info.loadLabel(this).toString();addMenuRow(panel,label,()->{dialog.dismiss();try{Intent view=new Intent(Intent.ACTION_VIEW,TvContract.buildChannelUriForPassthroughInput(info.getId()));startActivity(view);}catch(Exception e){toast("TV không hỗ trợ mở nguồn này từ ứng dụng");}});}
        dialog.setContentView(panel);configureDialog(dialog,dp(340));dialog.show();configureDialog(dialog,dp(340));
    }
    private boolean hasLocationPermission(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
    private void refreshNetwork(){try{
        ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network active=cm==null?null:cm.getActiveNetwork();NetworkCapabilities caps=active==null||cm==null?null:cm.getNetworkCapabilities(active);wifiActive=caps!=null&&caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI);
        if(network==null)return;if(caps!=null&&caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)){network.setContentDescription("Ethernet");setChipContent(network,"",true,R.drawable.ic_lan);return;}
        if(wifiActive){if(hasLocationPermission()){LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);boolean locationOn=Build.VERSION.SDK_INT<28||lm==null||lm.isLocationEnabled();if(locationOn){WifiManager wm=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);String ssid=wm==null?null:wm.getConnectionInfo().getSSID();if(ssid!=null&&!ssid.equalsIgnoreCase("<unknown ssid>")&&!ssid.isEmpty()){String name=ssid.replace("\"","");network.setContentDescription("Wi‑Fi: "+name);setChipContent(network,name,false,R.drawable.ic_wifi);return;}}}network.setContentDescription("Wi‑Fi");setChipContent(network,"",true,R.drawable.ic_wifi);return;}
        network.setContentDescription("Không có kết nối mạng");setChipContent(network,"",true,R.drawable.ic_wifi);
    }catch(Exception ignored){if(network!=null){network.setContentDescription("Wi‑Fi");setChipContent(network,"",true,R.drawable.ic_wifi);}}}
    private void refreshInputStatus(){if(inputButton==null)return;try{TvInputManager manager=(TvInputManager)getSystemService(TV_INPUT_SERVICE);if(manager!=null)for(TvInputInfo info:manager.getTvInputList())if(info.isPassthroughInput()){int state=manager.getInputState(info.getId());if(state==TvInputManager.INPUT_STATE_CONNECTED||state==TvInputManager.INPUT_STATE_CONNECTED_STANDBY){String label=info.loadLabel(this).toString();inputButton.setContentDescription("Nguồn vào: "+label);setChipContent(inputButton,label,false,R.drawable.ic_input);return;}}}catch(Exception ignored){}inputButton.setContentDescription("Nguồn vào");setChipContent(inputButton,"",true,R.drawable.ic_input);}
    private void startClock(){final TimeZone tz=TimeZone.getTimeZone("Asia/Bangkok");ticker=new Runnable(){public void run(){Date now=new Date();SimpleDateFormat tf=new SimpleDateFormat("HH:mm",Locale.ROOT);tf.setTimeZone(tz);clock.setText(tf.format(now));Locale vi=new Locale("vi","VN");SimpleDateFormat wf=new SimpleDateFormat("EEEE",vi);wf.setTimeZone(tz);weekday.setText("✥ "+wf.format(now).toUpperCase(vi)+" ✥");SimpleDateFormat df=new SimpleDateFormat("'▣ Ngày' d 'Tháng' M 'Năm' yyyy",vi);df.setTimeZone(tz);date.setText(df.format(now));Calendar day=Calendar.getInstance(tz,Locale.ROOT);day.setTime(now);String lunarKey=day.get(Calendar.YEAR)+"-"+day.get(Calendar.DAY_OF_YEAR);if(!lunarKey.equals(lastLunarDateKey)){lastLunarDateKey=lunarKey;cachedLunarDate=getLunarDate(now);cachedLunarYear=getLunarYear(now);}lunarDate.setText(cachedLunarDate);lunarYear.setText(cachedLunarYear);updateHolidayDisplay(now,tz);if(isInfoEnabled("show_weather",true))refreshWeatherIfNeeded(false);long delay=60000L-(System.currentTimeMillis()%60000L);handler.postDelayed(this,delay);}};handler.post(ticker);setStatsTickerEnabled(isInfoEnabled("show_device_stats",true));}
    private void setStatsTickerEnabled(boolean enabled){if(statsTicker!=null)handler.removeCallbacks(statsTicker);statsTicker=null;if(!enabled||isFinishing())return;statsTicker=new Runnable(){@Override public void run(){if(!isInfoEnabled("show_device_stats",true)||isFinishing())return;refreshDeviceStats();handler.postDelayed(this,DEVICE_STATS_REFRESH_INTERVAL_MS);}};handler.post(statsTicker);}
    private static Map<String,String> holidayMap(String[][] entries){HashMap<String,String> holidays=new HashMap<>();for(String[] entry:entries)holidays.put(entry[0],entry[1]);return Collections.unmodifiableMap(holidays);}
    private void updateHolidayDisplay(Date now,TimeZone tz){if(holidayPanel==null)return;if(!isInfoEnabled("show_holidays",true)){holidayPanel.setVisibility(View.GONE);return;}SimpleDateFormat dayKeyFormat=new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);dayKeyFormat.setTimeZone(tz);String dayKey=dayKeyFormat.format(now);if(dayKey.equals(lastHolidayDateKey))return;lastHolidayDateKey=dayKey;Calendar solarCalendar=Calendar.getInstance(tz,Locale.ROOT);solarCalendar.setTime(now);String solarName=SOLAR_HOLIDAYS.get(solarCalendar.get(Calendar.DAY_OF_MONTH)+"-"+(solarCalendar.get(Calendar.MONTH)+1));String lunarName=null;try{ChineseCalendar lunar=createLunarCalendar(now);lunarName=LUNAR_HOLIDAYS.get(lunar.get(android.icu.util.Calendar.DAY_OF_MONTH)+"-"+(lunar.get(android.icu.util.Calendar.MONTH)+1));}catch(Exception ignored){}boolean hasSolar=solarName!=null,hasLunar=lunarName!=null;holidaySolar.setText(hasSolar?solarName:"");holidayLunar.setText(hasLunar?lunarName:"");holidaySolarRow.setVisibility(hasSolar?View.VISIBLE:View.GONE);holidayLunarRow.setVisibility(hasLunar?View.VISIBLE:View.GONE);holidayPanel.setVisibility(hasSolar||hasLunar?View.VISIBLE:View.GONE);}
    private ChineseCalendar createLunarCalendar(Date date){ChineseCalendar lunar=new ChineseCalendar(android.icu.util.TimeZone.getTimeZone("Asia/Ho_Chi_Minh"),ULocale.forLocale(new Locale("vi","VN")));lunar.setTime(date);return lunar;}
    private String getLunarDate(Date date){try{ChineseCalendar lunar=createLunarCalendar(date);int day=lunar.get(android.icu.util.Calendar.DAY_OF_MONTH),month=lunar.get(android.icu.util.Calendar.MONTH)+1;String monthName;if(month==1)monthName="Giêng";else if(month==12)monthName="Chạp";else{String[] names={"","","Hai","Ba","Tư","Năm","Sáu","Bảy","Tám","Chín","Mười","Mười Một"};monthName=names[month];}return "☾ Mồng "+day+" Tháng "+monthName;}catch(Exception e){return "☾ Ngày âm lịch không khả dụng";}}
    private String getLunarYear(Date date){try{ChineseCalendar lunar=createLunarCalendar(date);int cycle=lunar.get(ChineseCalendar.YEAR);String[] can={"Giáp","Ất","Bính","Đinh","Mậu","Kỷ","Canh","Tân","Nhâm","Quý"};String[] chi={"Tý","Sửu","Dần","Mão","Thìn","Tỵ","Ngọ","Mùi","Thân","Dậu","Tuất","Hợi"};return "✧ NĂM "+can[(cycle-1)%10].toUpperCase(new Locale("vi","VN"))+" "+chi[(cycle-1)%12].toUpperCase(new Locale("vi","VN"))+" ✧";}catch(Exception e){return "✧ NĂM ÂM LỊCH ✧";}}
    private void refreshDeviceStats(){if(deviceStats==null||!isInfoEnabled("show_device_stats",true))return;long now=System.currentTimeMillis();if(now-lastDeviceStatsRefresh<DEVICE_STATS_REFRESH_INTERVAL_MS)return;lastDeviceStatsRefresh=now;try{String cpu=readCpuUsage();ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(memory);long total=memory.totalMem,used=Math.max(0,total-memory.availMem);StatFs fs=new StatFs(android.os.Environment.getDataDirectory().getPath());long storageTotal=fs.getTotalBytes(),storageUsed=storageTotal-fs.getAvailableBytes();deviceStats.setText(String.format(Locale.getDefault(),"◉ CPU %s · ◆ RAM %s/%s · ▤ ROM %s/%s",cpu,formatBytes(used),formatBytes(total),formatBytes(storageUsed),formatBytes(storageTotal)));}catch(Exception ignored){deviceStats.setText("◉ CPU -- · ◆ RAM -- · ▤ ROM --");}}
    private String readCpuUsage(){try(BufferedReader reader=new BufferedReader(new FileReader("/proc/stat"))){String line=reader.readLine();if(line==null||!line.startsWith("cpu "))return "--";String[] fields=line.trim().split("\\s+");long total=0;for(int i=1;i<fields.length;i++)total+=Long.parseLong(fields[i]);long idle=Long.parseLong(fields[4])+(fields.length>5?Long.parseLong(fields[5]):0);if(previousCpuTotal<0){previousCpuTotal=total;previousCpuIdle=idle;return "--";}long totalDelta=total-previousCpuTotal,idleDelta=idle-previousCpuIdle;previousCpuTotal=total;previousCpuIdle=idle;return totalDelta<=0?"--":Math.round(100d*(totalDelta-idleDelta)/totalDelta)+"%";}catch(Exception e){return "--";}}
    private String formatBytes(long bytes){if(bytes>=1024L*1024*1024)return String.format(Locale.getDefault(),"%.1f",bytes/(1024d*1024*1024))+" GB";return String.format(Locale.getDefault(),"%.0f",bytes/(1024d*1024))+" MB";}
    private TextView chip(String s,boolean circular){TextView v=text(s,circular?20:13,LIGHT,true);v.setGravity(Gravity.CENTER);v.setSingleLine(true);v.setEllipsize(android.text.TextUtils.TruncateAt.END);v.setBackground(null);v.setForeground(null);v.setDefaultFocusHighlightEnabled(false);v.setStateListAnimator(null);v.setElevation(0);v.setFocusable(true);setChipContent(v,s,circular);v.setOnFocusChangeListener((w,f)->updateChipFocus(v,f));return v;}
    private void setChipContent(TextView view,String content,boolean circular){setChipContent(view,content,circular,0);}
    private void setChipContent(TextView view,String content,boolean circular,int iconResource){view.setText(content);view.setTextSize(circular?20:13);view.setPadding(circular?0:dp(16),0,circular?0:dp(16),0);ViewGroup.LayoutParams raw=view.getLayoutParams();LinearLayout.LayoutParams params=raw instanceof LinearLayout.LayoutParams?(LinearLayout.LayoutParams)raw:new LinearLayout.LayoutParams(-2,dp(57));params.width=circular?dp(57):-2;params.height=dp(57);params.setMargins(dp(4),0,dp(4),0);view.setLayoutParams(params);view.setBackground(null);view.setForeground(null);if(iconResource!=0)setChipIcon(view,iconResource);else{view.setCompoundDrawables(null,null,null,null);view.setTag(null);}}
    private void setChipIcon(TextView view,int iconResource){Drawable icon=getDrawable(iconResource).mutate();boolean focused=view.hasFocus();icon.setTint(focused?0xFFFFE39A:LIGHT);Drawable frame=new IconFocusOutline(focused);LayerDrawable framedIcon=new LayerDrawable(new Drawable[]{frame,icon});framedIcon.setLayerInset(1,dp(5),dp(5),dp(5),dp(5));framedIcon.setBounds(0,0,dp(39),dp(39));view.setCompoundDrawables(framedIcon,null,null,null);view.setCompoundDrawablePadding(dp(9));view.setTag(iconResource);}
    private void updateChipFocus(TextView view,boolean focused){view.animate().scaleX(focused?1.1f:1f).scaleY(focused?1.1f:1f).translationY(0).setDuration(150).start();view.setTypeface(Typeface.create(focused?"sans-serif-black":"sans-serif",Typeface.BOLD));view.setTextColor(focused?0xFFE0F1C8:LIGHT);view.setBackground(null);view.setForeground(null);view.setDefaultFocusHighlightEnabled(false);view.setElevation(0);view.setShadowLayer(0,0,0,Color.TRANSPARENT);Object icon=view.getTag();if(icon instanceof Integer)setChipIcon(view,(Integer)icon);}
    private final class IconFocusOutline extends Drawable {private final Paint outlinePaint=new Paint(Paint.ANTI_ALIAS_FLAG);private final boolean visible;IconFocusOutline(boolean focused){visible=focused;outlinePaint.setColor(0xFFFFC857);outlinePaint.setStyle(Paint.Style.STROKE);outlinePaint.setStrokeWidth(dp(2));outlinePaint.setStrokeJoin(Paint.Join.ROUND);}@Override public void draw(android.graphics.Canvas canvas){if(!visible)return;android.graphics.Rect b=getBounds();float half=outlinePaint.getStrokeWidth()/2f;android.graphics.RectF r=new android.graphics.RectF(b.left+half,b.top+half,b.right-half,b.bottom-half);canvas.drawRoundRect(r,dp(8),dp(8),outlinePaint);}@Override public void setAlpha(int alpha){}@Override public void setColorFilter(android.graphics.ColorFilter filter){}@Override public int getOpacity(){return android.graphics.PixelFormat.TRANSLUCENT;}}
