    private final class LocationPinView extends View {private final Paint pinPaint=new Paint(Paint.ANTI_ALIAS_FLAG);LocationPinView(Context c){super(c);pinPaint.setColor(Color.WHITE);}@Override protected void onDraw(android.graphics.Canvas canvas){super.onDraw(canvas);int save=canvas.save();canvas.scale(getWidth()/100f,getHeight()/100f);android.graphics.Path path=new android.graphics.Path();path.setFillType(android.graphics.Path.FillType.EVEN_ODD);path.moveTo(50,2);path.cubicTo(23,2,6,20,6,43);path.cubicTo(6,64,27,84,50,99);path.cubicTo(73,84,94,64,94,43);path.cubicTo(94,20,77,2,50,2);path.close();path.addCircle(50,39,12,android.graphics.Path.Direction.CW);canvas.drawPath(path,pinPaint);canvas.restoreToCount(save);}}
